def choose_move(observation):
    # Defensive access
    pos = observation.get("position", {})
    x = pos.get("x", 0)
    y = pos.get("y", 0)

    # Try to infer simple goals from common fields
    grid = observation.get("grid", [])
    # If there is an agent target, try to move toward it
    target = observation.get("target", {})
    tpx = target.get("x", None)
    tpy = target.get("y", None)

    # Default stay
    dx = 0
    dy = 0

    # If a target exists, move one step toward it with bounds [-1,0,1]
    if tpx is not None and tpy is not None:
        if tpx > x:
            dx = 1
        elif tpx < x:
            dx = -1
        else:
            dx = 0

        if tpy > y:
            dy = 1
        elif tpy < y:
            dy = -1
        else:
            dy = 0

        # Normalize to ensure each in [-1,0,1]
        dx = max(-1, min(1, dx))
        dy = max(-1, min(1, dy))
        return [dx, dy]

    # If there is no explicit target, look for resources or enemies defensively
    # Scan nearby cells in a 3x3 neighborhood for a "resource" or "enemy" tag
    if grid:
        best_move = None
        best_score = -9999
        for oy in (-1, 0, 1):
            for ox in (-1, 0, 1):
                if ox == 0 and oy == 0:
                    continue
                nx = x + ox
                ny = y + oy
                if nx < 0 or ny < 0:
                    continue
                cell = None
                if isinstance(grid, list) and len(grid) > ny and isinstance(grid[ny], list) and len(grid[ny]) > nx:
                    cell = grid[ny][nx]
                # simple heuristic scoring
                score = 0
                if isinstance(cell, dict):
                    ctype = cell.get("type", "")
                    if ctype == "resource":
                        score += 5
                    if ctype == "enemy":
                        score -= 2
                    if ctype == "ally":
                        score += 1
                # prefer empty or neutral
                if cell is None:
                    score += 0
                if score > best_score:
                    best_score = score
                    best_move = (ox, oy)
        if best_move is not None:
            dx, dy = best_move
            dx = max(-1, min(1, dx))
            dy = max(-1, min(1, dy))
            return [dx, dy]

    # Fallback: random-like deterministic choice based on position
    # Simple pattern to ensure movement without staying still always
    if (x + y) % 2 == 0:
        return [1, 0]
    else:
        return [0, 1]

